/bin/bash -lc "node --input-type=module - <<'EOF'
import { spawnSync } from 'node:child_process';

const cases = [
  ['sample1', ['--a', \"select date_trunc('month', created_at) as month, category, sum(amount) as revenue, count(*) as orders from sales group by month, category order by month desc, revenue desc\"]],
  ['sample2', ['--a', \"select case when age < 13 then 'child' when age between 13 and 19 then 'teen' when age between 20 and 64 then 'adult' else 'senior' end as age_group, count(*) from users group by age_group\"]],
  ['sample3', ['--a', 'drop table if exists old_data; drop view if exists outdated_view; drop index if exists idx_old_index']],
  ['sample4', ['--a', \"select * from products where name like '%wireless%' and price between 50 and 500 order by price asc limit 10\"]],
  ['help', ['--help']],
  ['missing', []],
  ['missing-value', ['--a']],
  ['unknown-after-a', ['--a', 'x', '--foo', 'y']],
  ['inline-negative', ['--a=-x']],
  ['repeated-a', ['--a', 'first', '--a', 'second']],
];

let failures = 0;
for (const [name, args] of cases) {
  const js = spawnSync('node', ['/output/test4.mjs', ...args], { encoding: 'utf8' });
  const py = spawnSync('/workspace/dataset/test4_executable', args, { encoding: 'utf8' });

  let stdoutMatch = js.stdout === py.stdout;
  let stderrMatch = js.stderr === py.stderr;

  if (name === 'help' || name === 'missing' || name === 'missing-value' || name === 'unknown-after-a') {
    stderrMatch = js.stderr.replaceAll('test4.mjs', 'test4_executable') === py.stderr;
    stdoutMatch = js.stdout.replaceAll('test4.mjs', 'test4_executable') === py.stdout;
  }

  const codeMatch = js.status === py.status;
  const ok = stdoutMatch && stderrMatch && codeMatch;
  if ("'!ok) {
    failures += 1;
    console.log(`FAIL ${name}`);
    console.log({
      jsStatus: js.status,
      pyStatus: py.status,
      jsStdout: js.stdout,
      pyStdout: py.stdout,
      jsStderr: js.stderr,
      pyStderr: py.stderr,
    });
  }
}

if (failures === 0) {
  console.log('"'All verification cases matched expected behavior.');
}
EOF"

